#!/usr/bin/env bash
# SPDX-FileCopyrightText: tix-mobile contributors
# SPDX-License-Identifier: AGPL-3.0-or-later
#
# The tix-mobile module's build inside flatpak-builder, offline. Every input is
# a source in flatpak/red.tix.tix_mobile.yml: the Flutter SDK and its pub
# packages (generated by flatpak-flutter), Go, and the tix source at the commit
# tix.lock pins with its Go modules vendored.
#
# One script rather than build-commands because each build-command runs in a
# fresh shell, and HOME, PATH and the Go settings have to hold for all of it.

set -euo pipefail

src=$(pwd)
export HOME="${FLATPAK_BUILDER_BUILDDIR:-$src}/.home"
export PATH="/app/lib/go/bin:$src/flutter/bin:$PATH"
export PUB_CACHE="$src/.pub-cache"
# The Dart build hook starts Go with a trimmed environment, so Go's settings
# go into its config file under HOME, which the hook does pass on.
unset XDG_CONFIG_HOME
mkdir -p "$HOME"
go env -w GOTOOLCHAIN=local GOPROXY=off GOFLAGS=-mod=vendor

# hook/build.dart reuses a tix checkout it finds in its cache instead of
# fetching one, which is how the vendored source gets in without a network.
commit=$(sed -nE 's/^commit = ([0-9a-f]{40})$/\1/p' tix.lock)
[ -n "$commit" ] || { echo "no commit in tix.lock" >&2; exit 1; }
mkdir -p "$HOME/.cache/tix-mobile/libtix/src"
cp -a tix-src "$HOME/.cache/tix-mobile/libtix/src/$commit"

flutter config --no-analytics --no-cli-animations >/dev/null
flutter pub get --offline

python3 scripts/metainfo-releases.py CHANGELOG.md linux/packaging/red.tix.tix_mobile.metainfo.xml

version=$(sed -nE 's/^version: ([0-9]+\.[0-9]+\.[0-9]+).*/\1/p' pubspec.yaml)
flutter build linux --release --build-name="$version"

case "$(uname -m)" in
  x86_64) arch=x64 ;;
  aarch64) arch=arm64 ;;
  *) echo "unsupported architecture $(uname -m)" >&2; exit 1 ;;
esac
bundle="build/linux/$arch/release/bundle"
scripts/engine-check.sh bundle "$bundle"

mkdir -p /app/tix-mobile /app/bin
cp -a "$bundle"/. /app/tix-mobile/
ln -sf /app/tix-mobile/tix_mobile /app/bin/tix_mobile
# The bundle carries the desktop entry, metainfo and icons under share/ (see
# linux/CMakeLists.txt); Flatpak wants them under /app/share.
cp -a /app/tix-mobile/share /app/
rm -rf /app/tix-mobile/share
